bootforge/sql-data/mutations-and-modelin.starter:
export function buildTaskQuery(filters, page, pageSize) {
  // build { sql, params } — values go in params, never in the sql text
}

bootforge/sql-data/mutations-and-modelin.solution:
export function buildTaskQuery(filters, page, pageSize) {
  const keys = Object.keys(filters);
  const parts = ['SELECT id, title, status, priority FROM tasks'];
  const params = [];
  if (keys.length > 0) {
    parts.push('WHERE ' + keys.map((k) => k + ' = ?').join(' AND '));
    params.push(...keys.map((k) => filters[k]));
  }
  parts.push('ORDER BY id');
  parts.push('LIMIT ? OFFSET ?');
  const p = Math.max(1, page);
  params.push(pageSize, (p - 1) * pageSize);
  return { sql: parts.join(' '), params };
}
